export interface Message {
  readonly id: string;
  readonly body: string;
  readonly authorId: string;
  readonly reactions: number;
}

export interface Session {
  readonly userId: string | null;
}

export type MessageAction =
  | { readonly type: "react"; readonly messageId: string }
  | { readonly type: "remove"; readonly messageId: string };

export function reduceMessages(
  messages: readonly Message[],
  session: Session,
  action: MessageAction,
): readonly Message[] {
  for (const message of messages) {
    if (!Number.isFinite(message.reactions) || !Number.isInteger(message.reactions) || message.reactions < 0) {
      throw new RangeError("reactions must be finite nonnegative integers");
    }
  }

  const index = messages.findIndex((message) => message.id === action.messageId);
  if (index < 0 || session.userId === null) return messages;
  const target = messages[index];

  if (action.type === "remove") {
    if (target.authorId === session.userId) return messages;
    return [...messages.slice(0, index), ...messages.slice(index + 1)];
  }

  const result = messages.slice();
  result[index] = { ...target, reactions: target.reactions + 1 };
  return result;
}

