import { reduceMessages, Message, MessageAction, Session } from "./solution";

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}

function expectRangeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const first: Message = Object.freeze({ id: "m1", body: "one", authorId: "u1", reactions: 2 });
const second: Message = Object.freeze({ id: "m2", body: "two", authorId: "u2", reactions: 0 });
const messages: readonly Message[] = Object.freeze([first, second]);
const loggedIn: Session = Object.freeze({ userId: "u1" });
const anonymous: Session = Object.freeze({ userId: null });

const reactAction: MessageAction = Object.freeze({ type: "react", messageId: "m2" });
const reacted = reduceMessages(messages, loggedIn, reactAction);
equal(reacted === messages, false, "successful reaction returns a new array");
equal(reacted.length, 2, "reaction preserves length");
equal(reacted[0], first, "unchanged message object is reused");
equal(reacted[1] === second, false, "reacted message is copied");
equal(reacted[1].id, "m2", "reacted id is preserved");
equal(reacted[1].body, "two", "reacted body is preserved");
equal(reacted[1].authorId, "u2", "reacted author is preserved");
equal(reacted[1].reactions, 1, "reaction is incremented");
equal(second.reactions, 0, "original message is unchanged");

const anonymousResult = reduceMessages(messages, anonymous, reactAction);
equal(anonymousResult, messages, "anonymous reaction returns original reference");
const unknownResult = reduceMessages(messages, loggedIn, { type: "react", messageId: "missing" });
equal(unknownResult, messages, "unknown reaction returns original reference");
const unauthorizedRemove = reduceMessages(messages, loggedIn, { type: "remove", messageId: "m2" });
equal(unauthorizedRemove, messages, "unauthorized removal returns original reference");

const removed = reduceMessages(messages, loggedIn, { type: "remove", messageId: "m1" });
equal(removed === messages, false, "successful removal returns a new array");
equal(removed.length, 1, "successful removal changes length");
equal(removed[0], second, "remaining object is reused");

equal(reduceMessages([], loggedIn, { type: "react", messageId: "m1" }).length, 0, "empty input is valid");
equal(loggedIn.userId, "u1", "session is not mutated");
equal(reactAction.messageId, "m2", "action is not mutated");

const badNaN: readonly Message[] = [{ id: "bad", body: "x", authorId: "u1", reactions: Number.NaN }];
expectRangeError(() => reduceMessages(badNaN, anonymous, { type: "react", messageId: "missing" }), "validation occurs before unauthorized action");
expectRangeError(() => reduceMessages([{ id: "bad", body: "x", authorId: "u1", reactions: -1 }], loggedIn, { type: "remove", messageId: "bad" }), "negative reactions");
expectRangeError(() => reduceMessages([{ id: "bad", body: "x", authorId: "u1", reactions: 1.5 }], loggedIn, { type: "react", messageId: "bad" }), "fractional reactions");
expectRangeError(() => reduceMessages([{ id: "bad", body: "x", authorId: "u1", reactions: Number.POSITIVE_INFINITY }], loggedIn, { type: "react", messageId: "bad" }), "infinite reactions");

